"""Order fulfillment package: SQLite-backed service API."""

from __future__ import annotations

import math
import sqlite3
from pathlib import Path
from typing import Any, Callable


class OrderError(Exception):
    """Stable order-domain error."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None):
        self.code = code
        self.message = message
        self.details: dict[str, object] = details if details is not None else {}
        super().__init__(message)

    def __str__(self) -> str:
        return self.message


def _is_int(value: object) -> bool:
    return type(value) is int


def _is_finite_number(value: object) -> bool:
    if type(value) is bool:
        return False
    if type(value) is int:
        return True
    if type(value) is float:
        return math.isfinite(value)
    return False


def _require_nonempty_str(value: object, field: str) -> str:
    if type(value) is not str or value == "" or value.strip() == "":
        raise OrderError(
            "INVALID_INPUT",
            f"invalid {field}",
            {"field": field},
        )
    # no implicit trimming: whitespace-only already rejected; embedded whitespace OK
    # but pure whitespace-only: value.strip() == "" catches it
    # contract: "non-empty strings after no implicit trimming; whitespace-only is invalid"
    # so "  " is invalid, " a " is valid as-is (not trimmed)
    if value.strip() == "":
        raise OrderError(
            "INVALID_INPUT",
            f"invalid {field}",
            {"field": field},
        )
    return value


def _require_nonempty_str_loose(value: object, field: str) -> str:
    """Non-empty string; whitespace-only invalid; no trimming applied to stored value."""
    if type(value) is not str:
        raise OrderError("INVALID_INPUT", f"invalid {field}", {"field": field})
    if value == "" or value.strip() == "":
        raise OrderError("INVALID_INPUT", f"invalid {field}", {"field": field})
    return value


def _now(clock: Callable[[], object]) -> float | int:
    try:
        value = clock()
    except Exception as exc:  # noqa: BLE001
        raise OrderError(
            "INVALID_DEPENDENCY",
            "clock failed",
            {"dependency": "clock", "error": str(exc)},
        ) from exc
    if not _is_finite_number(value):
        raise OrderError(
            "INVALID_DEPENDENCY",
            "clock returned non-finite number",
            {"dependency": "clock"},
        )
    return value  # type: ignore[return-value]


def _new_id(id_factory: Callable[[], object]) -> str:
    try:
        value = id_factory()
    except Exception as exc:  # noqa: BLE001
        raise OrderError(
            "INVALID_DEPENDENCY",
            "id_factory failed",
            {"dependency": "id_factory", "error": str(exc)},
        ) from exc
    if type(value) is not str or value == "" or value.strip() == "":
        raise OrderError(
            "INVALID_DEPENDENCY",
            "id_factory returned invalid id",
            {"dependency": "id_factory"},
        )
    return value


SCHEMA_VERSION = 1

_SCHEMA_SQL = """
CREATE TABLE IF NOT EXISTS meta (
    key TEXT PRIMARY KEY NOT NULL,
    value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS stock (
    sku TEXT PRIMARY KEY NOT NULL,
    available INTEGER NOT NULL CHECK (available >= 0)
);

CREATE TABLE IF NOT EXISTS orders (
    order_id TEXT PRIMARY KEY NOT NULL,
    idempotency_key TEXT NOT NULL UNIQUE,
    status TEXT NOT NULL CHECK (status IN ('pending', 'paid', 'shipped', 'cancelled')),
    total_cents INTEGER NOT NULL CHECK (total_cents >= 0),
    payment_id TEXT,
    payment_amount_cents INTEGER,
    created_at REAL NOT NULL,
    updated_at REAL NOT NULL
);

CREATE TABLE IF NOT EXISTS order_items (
    order_id TEXT NOT NULL,
    sku TEXT NOT NULL,
    quantity INTEGER NOT NULL CHECK (quantity > 0),
    unit_price_cents INTEGER NOT NULL CHECK (unit_price_cents >= 0),
    PRIMARY KEY (order_id, sku),
    FOREIGN KEY (order_id) REFERENCES orders(order_id)
);

CREATE TABLE IF NOT EXISTS payments (
    payment_id TEXT PRIMARY KEY NOT NULL,
    order_id TEXT NOT NULL,
    amount_cents INTEGER NOT NULL,
    FOREIGN KEY (order_id) REFERENCES orders(order_id)
);

CREATE INDEX IF NOT EXISTS idx_orders_idempotency ON orders(idempotency_key);
"""


class OrderService:
    """SQLite-backed order service."""

    def __init__(self, db_path, *, clock, id_factory):
        if clock is None or not callable(clock):
            raise OrderError("INVALID_INPUT", "clock must be callable", {"field": "clock"})
        if id_factory is None or not callable(id_factory):
            raise OrderError("INVALID_INPUT", "id_factory must be callable", {"field": "id_factory"})
        self._clock = clock
        self._id_factory = id_factory
        self._db_path = str(db_path)
        parent = Path(self._db_path).parent
        if str(parent) not in ("", "."):
            parent.mkdir(parents=True, exist_ok=True)
        try:
            self._conn = sqlite3.connect(self._db_path, isolation_level=None, check_same_thread=False)
            self._conn.row_factory = sqlite3.Row
            self._conn.execute("PRAGMA foreign_keys = ON")
            self._conn.execute("PRAGMA busy_timeout = 5000")
            self._ensure_schema()
        except OrderError:
            raise
        except sqlite3.Error as exc:
            raise OrderError("STORAGE_ERROR", "failed to open database", {"error": str(exc)}) from exc

    def _ensure_schema(self) -> None:
        try:
            cur = self._conn.execute(
                "SELECT name FROM sqlite_master WHERE type='table' AND name='meta'"
            )
            has_meta = cur.fetchone() is not None
            if not has_meta:
                # brand new or empty DB
                tables = self._conn.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'"
                ).fetchall()
                if tables:
                    # unknown tables without meta
                    raise OrderError(
                        "SCHEMA_MISMATCH",
                        "unknown or incompatible schema",
                        {},
                    )
                self._conn.executescript(_SCHEMA_SQL)
                self._conn.execute(
                    "INSERT INTO meta(key, value) VALUES ('schema_version', ?)",
                    (str(SCHEMA_VERSION),),
                )
                return

            row = self._conn.execute(
                "SELECT value FROM meta WHERE key = 'schema_version'"
            ).fetchone()
            if row is None:
                raise OrderError("SCHEMA_MISMATCH", "missing schema_version", {})
            try:
                version = int(row["value"])
            except (TypeError, ValueError) as exc:
                raise OrderError("SCHEMA_MISMATCH", "invalid schema_version", {}) from exc
            if version != SCHEMA_VERSION:
                raise OrderError(
                    "SCHEMA_MISMATCH",
                    "incompatible schema version",
                    {"schema_version": version},
                )
            # ensure required tables exist
            required = {"meta", "stock", "orders", "order_items", "payments"}
            existing = {
                r["name"]
                for r in self._conn.execute(
                    "SELECT name FROM sqlite_master WHERE type='table'"
                ).fetchall()
            }
            if not required.issubset(existing):
                raise OrderError("SCHEMA_MISMATCH", "missing required tables", {})
            # idempotent: ensure indexes/tables from script for incomplete installs
            self._conn.executescript(_SCHEMA_SQL)
        except OrderError:
            raise
        except sqlite3.Error as exc:
            raise OrderError("STORAGE_ERROR", "schema initialization failed", {"error": str(exc)}) from exc

    def _begin(self) -> None:
        self._conn.execute("BEGIN IMMEDIATE")

    def _commit(self) -> None:
        self._conn.execute("COMMIT")

    def _rollback(self) -> None:
        try:
            self._conn.execute("ROLLBACK")
        except sqlite3.Error:
            pass

    def set_stock(self, sku: str, quantity: int) -> dict:
        sku_s = _require_nonempty_str_loose(sku, "sku")
        if not _is_int(quantity) or quantity < 0:
            raise OrderError("INVALID_INPUT", "invalid quantity", {"field": "quantity"})
        try:
            self._begin()
            self._conn.execute(
                """
                INSERT INTO stock(sku, available) VALUES (?, ?)
                ON CONFLICT(sku) DO UPDATE SET available = excluded.available
                """,
                (sku_s, quantity),
            )
            row = self._conn.execute(
                "SELECT sku, available FROM stock WHERE sku = ?", (sku_s,)
            ).fetchone()
            self._commit()
            return {"sku": row["sku"], "available": int(row["available"])}
        except OrderError:
            self._rollback()
            raise
        except sqlite3.Error as exc:
            self._rollback()
            raise OrderError("STORAGE_ERROR", "set_stock failed", {"error": str(exc)}) from exc

    def _validate_items(self, items: object) -> list[tuple[str, int, int]]:
        if type(items) is not list or len(items) == 0:
            raise OrderError("INVALID_INPUT", "items must be a non-empty list", {"field": "items"})
        seen: set[str] = set()
        canonical: list[tuple[str, int, int]] = []
        for idx, item in enumerate(items):
            if type(item) is not dict:
                raise OrderError(
                    "INVALID_INPUT",
                    "item must be an object",
                    {"field": "items", "index": idx},
                )
            allowed = {"sku", "quantity", "unit_price_cents"}
            if set(item.keys()) != allowed:
                raise OrderError(
                    "INVALID_INPUT",
                    "item fields must be exactly sku, quantity, unit_price_cents",
                    {"field": "items", "index": idx},
                )
            sku = _require_nonempty_str_loose(item["sku"], "sku")
            qty = item["quantity"]
            price = item["unit_price_cents"]
            if not _is_int(qty) or qty <= 0:
                raise OrderError(
                    "INVALID_INPUT",
                    "invalid item quantity",
                    {"field": "quantity", "index": idx},
                )
            if not _is_int(price) or price < 0:
                raise OrderError(
                    "INVALID_INPUT",
                    "invalid unit_price_cents",
                    {"field": "unit_price_cents", "index": idx},
                )
            if sku in seen:
                raise OrderError(
                    "INVALID_INPUT",
                    "duplicate sku in items",
                    {"field": "sku", "sku": sku},
                )
            seen.add(sku)
            canonical.append((sku, qty, price))
        canonical.sort(key=lambda t: t[0])
        return canonical

    def _load_order_items(self, order_id: str) -> list[dict[str, object]]:
        rows = self._conn.execute(
            """
            SELECT sku, quantity, unit_price_cents
            FROM order_items
            WHERE order_id = ?
            ORDER BY sku ASC
            """,
            (order_id,),
        ).fetchall()
        return [
            {
                "sku": r["sku"],
                "quantity": int(r["quantity"]),
                "unit_price_cents": int(r["unit_price_cents"]),
            }
            for r in rows
        ]

    def _order_dict(self, row: sqlite3.Row) -> dict[str, object]:
        payment_id = row["payment_id"]
        return {
            "order_id": row["order_id"],
            "idempotency_key": row["idempotency_key"],
            "status": row["status"],
            "items": self._load_order_items(row["order_id"]),
            "total_cents": int(row["total_cents"]),
            "payment_id": payment_id,
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
        }

    def create_order(self, idempotency_key: str, items: list[dict]) -> dict:
        key = _require_nonempty_str_loose(idempotency_key, "idempotency_key")
        canonical = self._validate_items(items)
        total = sum(q * p for _, q, p in canonical)

        try:
            self._begin()
            existing = self._conn.execute(
                "SELECT * FROM orders WHERE idempotency_key = ?", (key,)
            ).fetchone()
            if existing is not None:
                existing_items = self._load_order_items(existing["order_id"])
                existing_canon = [
                    (it["sku"], it["quantity"], it["unit_price_cents"]) for it in existing_items
                ]
                if existing_canon == canonical:
                    result = self._order_dict(existing)
                    self._commit()
                    return result
                self._rollback()
                raise OrderError(
                    "IDEMPOTENCY_CONFLICT",
                    "idempotency key reused with different items",
                    {"idempotency_key": key},
                )

            # check stock for all SKUs first
            for sku, qty, _price in canonical:
                stock_row = self._conn.execute(
                    "SELECT available FROM stock WHERE sku = ?", (sku,)
                ).fetchone()
                available = int(stock_row["available"]) if stock_row is not None else 0
                if available < qty:
                    self._rollback()
                    raise OrderError(
                        "INSUFFICIENT_STOCK",
                        "insufficient stock",
                        {"sku": sku, "requested": qty, "available": available},
                    )

            # generate unique order id (max 3 factory calls total)
            order_id: str | None = None
            last_err: Exception | None = None
            for _attempt in range(3):
                try:
                    candidate = _new_id(self._id_factory)
                except OrderError:
                    self._rollback()
                    raise
                clash = self._conn.execute(
                    "SELECT 1 FROM orders WHERE order_id = ?", (candidate,)
                ).fetchone()
                if clash is None:
                    order_id = candidate
                    break
                last_err = OrderError("ID_COLLISION", "order id collision", {"order_id": candidate})
            if order_id is None:
                self._rollback()
                raise last_err if last_err is not None else OrderError(
                    "ID_COLLISION", "order id collision", {}
                )

            try:
                ts = _now(self._clock)
            except OrderError:
                self._rollback()
                raise

            # decrement stock
            for sku, qty, _price in canonical:
                self._conn.execute(
                    "UPDATE stock SET available = available - ? WHERE sku = ?",
                    (qty, sku),
                )

            self._conn.execute(
                """
                INSERT INTO orders(
                    order_id, idempotency_key, status, total_cents,
                    payment_id, payment_amount_cents, created_at, updated_at
                ) VALUES (?, ?, 'pending', ?, NULL, NULL, ?, ?)
                """,
                (order_id, key, total, ts, ts),
            )
            for sku, qty, price in canonical:
                self._conn.execute(
                    """
                    INSERT INTO order_items(order_id, sku, quantity, unit_price_cents)
                    VALUES (?, ?, ?, ?)
                    """,
                    (order_id, sku, qty, price),
                )

            row = self._conn.execute(
                "SELECT * FROM orders WHERE order_id = ?", (order_id,)
            ).fetchone()
            result = self._order_dict(row)
            self._commit()
            return result
        except OrderError:
            self._rollback()
            raise
        except sqlite3.Error as exc:
            self._rollback()
            raise OrderError("STORAGE_ERROR", "create_order failed", {"error": str(exc)}) from exc

    def pay_order(self, order_id: str, payment_id: str, amount_cents: int) -> dict:
        oid = _require_nonempty_str_loose(order_id, "order_id")
        pid = _require_nonempty_str_loose(payment_id, "payment_id")
        if not _is_int(amount_cents) or amount_cents < 0:
            raise OrderError("INVALID_INPUT", "invalid amount_cents", {"field": "amount_cents"})

        try:
            self._begin()
            order = self._conn.execute(
                "SELECT * FROM orders WHERE order_id = ?", (oid,)
            ).fetchone()
            if order is None:
                self._rollback()
                raise OrderError("NOT_FOUND", "order not found", {"order_id": oid})

            # amount mismatch before mutation (for pending)
            if order["status"] == "pending" and int(order["total_cents"]) != amount_cents:
                self._rollback()
                raise OrderError(
                    "AMOUNT_MISMATCH",
                    "payment amount does not match order total",
                    {
                        "order_id": oid,
                        "expected": int(order["total_cents"]),
                        "got": amount_cents,
                    },
                )

            # idempotent exact triple for already-paid/shipped/cancelled
            if order["status"] in ("paid", "shipped", "cancelled"):
                if (
                    order["payment_id"] == pid
                    and order["payment_amount_cents"] is not None
                    and int(order["payment_amount_cents"]) == amount_cents
                ):
                    result = self._order_dict(order)
                    self._commit()
                    return result
                # payment conflict
                self._rollback()
                raise OrderError(
                    "PAYMENT_CONFLICT",
                    "payment conflict",
                    {"order_id": oid, "payment_id": pid},
                )

            if order["status"] != "pending":
                self._rollback()
                raise OrderError(
                    "INVALID_STATE",
                    f"cannot pay order in status {order['status']}",
                    {"order_id": oid, "status": order["status"]},
                )

            # check payment_id uniqueness globally
            existing_pay = self._conn.execute(
                "SELECT * FROM payments WHERE payment_id = ?", (pid,)
            ).fetchone()
            if existing_pay is not None:
                self._rollback()
                raise OrderError(
                    "PAYMENT_CONFLICT",
                    "payment id already used",
                    {"payment_id": pid},
                )

            try:
                ts = _now(self._clock)
            except OrderError:
                self._rollback()
                raise

            self._conn.execute(
                """
                UPDATE orders
                SET status = 'paid', payment_id = ?, payment_amount_cents = ?, updated_at = ?
                WHERE order_id = ?
                """,
                (pid, amount_cents, ts, oid),
            )
            self._conn.execute(
                "INSERT INTO payments(payment_id, order_id, amount_cents) VALUES (?, ?, ?)",
                (pid, oid, amount_cents),
            )
            row = self._conn.execute(
                "SELECT * FROM orders WHERE order_id = ?", (oid,)
            ).fetchone()
            result = self._order_dict(row)
            self._commit()
            return result
        except OrderError:
            self._rollback()
            raise
        except sqlite3.Error as exc:
            self._rollback()
            raise OrderError("STORAGE_ERROR", "pay_order failed", {"error": str(exc)}) from exc

    def cancel_order(self, order_id: str) -> dict:
        oid = _require_nonempty_str_loose(order_id, "order_id")
        try:
            self._begin()
            order = self._conn.execute(
                "SELECT * FROM orders WHERE order_id = ?", (oid,)
            ).fetchone()
            if order is None:
                self._rollback()
                raise OrderError("NOT_FOUND", "order not found", {"order_id": oid})

            if order["status"] == "cancelled":
                result = self._order_dict(order)
                self._commit()
                return result

            if order["status"] == "shipped":
                self._rollback()
                raise OrderError(
                    "INVALID_STATE",
                    "cannot cancel shipped order",
                    {"order_id": oid, "status": "shipped"},
                )

            if order["status"] not in ("pending", "paid"):
                self._rollback()
                raise OrderError(
                    "INVALID_STATE",
                    f"cannot cancel order in status {order['status']}",
                    {"order_id": oid, "status": order["status"]},
                )

            try:
                ts = _now(self._clock)
            except OrderError:
                self._rollback()
                raise

            items = self._load_order_items(oid)
            for it in items:
                # release reserved stock: insert stock row if missing then add back
                self._conn.execute(
                    """
                    INSERT INTO stock(sku, available) VALUES (?, ?)
                    ON CONFLICT(sku) DO UPDATE SET available = available + excluded.available
                    """,
                    (it["sku"], it["quantity"]),
                )

            self._conn.execute(
                "UPDATE orders SET status = 'cancelled', updated_at = ? WHERE order_id = ?",
                (ts, oid),
            )
            row = self._conn.execute(
                "SELECT * FROM orders WHERE order_id = ?", (oid,)
            ).fetchone()
            result = self._order_dict(row)
            self._commit()
            return result
        except OrderError:
            self._rollback()
            raise
        except sqlite3.Error as exc:
            self._rollback()
            raise OrderError("STORAGE_ERROR", "cancel_order failed", {"error": str(exc)}) from exc

    def ship_order(self, order_id: str) -> dict:
        oid = _require_nonempty_str_loose(order_id, "order_id")
        try:
            self._begin()
            order = self._conn.execute(
                "SELECT * FROM orders WHERE order_id = ?", (oid,)
            ).fetchone()
            if order is None:
                self._rollback()
                raise OrderError("NOT_FOUND", "order not found", {"order_id": oid})

            if order["status"] == "shipped":
                result = self._order_dict(order)
                self._commit()
                return result

            if order["status"] != "paid":
                self._rollback()
                raise OrderError(
                    "INVALID_STATE",
                    f"cannot ship order in status {order['status']}",
                    {"order_id": oid, "status": order["status"]},
                )

            try:
                ts = _now(self._clock)
            except OrderError:
                self._rollback()
                raise

            self._conn.execute(
                "UPDATE orders SET status = 'shipped', updated_at = ? WHERE order_id = ?",
                (ts, oid),
            )
            row = self._conn.execute(
                "SELECT * FROM orders WHERE order_id = ?", (oid,)
            ).fetchone()
            result = self._order_dict(row)
            self._commit()
            return result
        except OrderError:
            self._rollback()
            raise
        except sqlite3.Error as exc:
            self._rollback()
            raise OrderError("STORAGE_ERROR", "ship_order failed", {"error": str(exc)}) from exc

    def get_order(self, order_id: str) -> dict:
        oid = _require_nonempty_str_loose(order_id, "order_id")
        try:
            self._begin()
            order = self._conn.execute(
                "SELECT * FROM orders WHERE order_id = ?", (oid,)
            ).fetchone()
            if order is None:
                self._rollback()
                raise OrderError("NOT_FOUND", "order not found", {"order_id": oid})
            result = self._order_dict(order)
            self._commit()
            return result
        except OrderError:
            self._rollback()
            raise
        except sqlite3.Error as exc:
            self._rollback()
            raise OrderError("STORAGE_ERROR", "get_order failed", {"error": str(exc)}) from exc


__all__ = ["OrderError", "OrderService"]

