"""Order fulfillment JSON CLI entry point."""

from __future__ import annotations

import argparse
import json
import sys
import time
import uuid
from typing import Any

from src.order_fulfillment import OrderError, OrderService


def _emit(obj: dict[str, Any], exit_code: int) -> None:
    sys.stdout.write(
        json.dumps(obj, sort_keys=True, separators=(",", ":"), allow_nan=False, ensure_ascii=False)
        + "\n"
    )
    sys.stdout.flush()
    raise SystemExit(exit_code)


def _read_input(command: str) -> dict[str, Any]:
    optional_empty = command in ("init", "recover", "list")  # not used for orders but keep pattern
    # For order CLI: all commands that need fields require input; none are fully optional except none.
    # Contract: "Commands consume exactly one JSON object from one non-empty stdin line,
    # except init, recover, and list" — order CLI has none of those, so always require line?
    # But empty might still be given. For stock/create/pay etc. missing fields -> INVALID_INPUT.
    raw = sys.stdin.readline()
    if raw == "":
        # EOF with no line
        if optional_empty:
            return {}
        # treat as empty object for robustness? Contract says non-empty line except those three.
        # order has no init/recover/list — invalid empty input
        raise OrderError("INVALID_INPUT", "expected one JSON object on stdin", {})
    line = raw
    if line.endswith("\n"):
        line = line[:-1]
    if line.endswith("\r"):
        line = line[:-1]
    if line == "":
        raise OrderError("INVALID_INPUT", "expected one JSON object on stdin", {})
    try:
        data = json.loads(line)
    except json.JSONDecodeError as exc:
        raise OrderError("INVALID_INPUT", "invalid JSON", {"error": str(exc)}) from exc
    if type(data) is not dict:
        raise OrderError("INVALID_INPUT", "input must be a JSON object", {})
    return data


def _require_fields(data: dict[str, Any], fields: list[str]) -> None:
    for f in fields:
        if f not in data:
            raise OrderError("INVALID_INPUT", f"missing field {f}", {"field": f})


def main() -> None:
    parser = argparse.ArgumentParser(prog="order_fulfillment", add_help=True)
    parser.add_argument("--db", required=True)
    parser.add_argument(
        "command",
        choices=["stock", "create", "pay", "cancel", "ship", "get"],
    )
    try:
        args = parser.parse_args()
    except SystemExit as exc:
        # argparse errors -> exit 2 with envelope if possible
        code = exc.code if isinstance(exc.code, int) else 2
        if code == 0:
            raise
        _emit(
            {
                "ok": False,
                "error": {
                    "code": "INVALID_INPUT",
                    "message": "invalid CLI arguments",
                    "details": {},
                },
            },
            2,
        )
        return

    try:
        data = _read_input(args.command)
        service = OrderService(args.db, clock=time.time, id_factory=lambda: uuid.uuid4().hex)

        if args.command == "stock":
            _require_fields(data, ["sku", "quantity"])
            unknown = set(data.keys()) - {"sku", "quantity"}
            if unknown:
                raise OrderError("INVALID_INPUT", "unknown fields", {"fields": sorted(unknown)})
            result = service.set_stock(data["sku"], data["quantity"])
        elif args.command == "create":
            _require_fields(data, ["idempotency_key", "items"])
            unknown = set(data.keys()) - {"idempotency_key", "items"}
            if unknown:
                raise OrderError("INVALID_INPUT", "unknown fields", {"fields": sorted(unknown)})
            result = service.create_order(data["idempotency_key"], data["items"])
        elif args.command == "pay":
            _require_fields(data, ["order_id", "payment_id", "amount_cents"])
            unknown = set(data.keys()) - {"order_id", "payment_id", "amount_cents"}
            if unknown:
                raise OrderError("INVALID_INPUT", "unknown fields", {"fields": sorted(unknown)})
            result = service.pay_order(data["order_id"], data["payment_id"], data["amount_cents"])
        elif args.command == "cancel":
            _require_fields(data, ["order_id"])
            unknown = set(data.keys()) - {"order_id"}
            if unknown:
                raise OrderError("INVALID_INPUT", "unknown fields", {"fields": sorted(unknown)})
            result = service.cancel_order(data["order_id"])
        elif args.command == "ship":
            _require_fields(data, ["order_id"])
            unknown = set(data.keys()) - {"order_id"}
            if unknown:
                raise OrderError("INVALID_INPUT", "unknown fields", {"fields": sorted(unknown)})
            result = service.ship_order(data["order_id"])
        elif args.command == "get":
            _require_fields(data, ["order_id"])
            unknown = set(data.keys()) - {"order_id"}
            if unknown:
                raise OrderError("INVALID_INPUT", "unknown fields", {"fields": sorted(unknown)})
            result = service.get_order(data["order_id"])
        else:
            raise OrderError("INVALID_INPUT", "unknown command", {"command": args.command})

        _emit({"ok": True, "result": result}, 0)
    except OrderError as err:
        exit_code = 3 if err.code == "STORAGE_ERROR" else 2
        _emit(
            {
                "ok": False,
                "error": {
                    "code": err.code,
                    "message": err.message,
                    "details": err.details,
                },
            },
            exit_code,
        )
    except Exception as exc:  # noqa: BLE001
        _emit(
            {
                "ok": False,
                "error": {
                    "code": "STORAGE_ERROR",
                    "message": "internal storage failure",
                    "details": {"error": str(exc)},
                },
            },
            3,
        )


if __name__ == "__main__":
    main()

