"""Delivery spool JSON CLI entry point."""

from __future__ import annotations

import argparse
import json
import sys
import time
from typing import Any

from src.delivery_spool import Limits, Spool, SpoolError


def _emit(obj: dict[str, Any], exit_code: int) -> None:
    sys.stdout.write(
        json.dumps(obj, sort_keys=True, separators=(",", ":"), allow_nan=False, ensure_ascii=False)
        + "\n"
    )
    sys.stdout.flush()
    raise SystemExit(exit_code)


def _read_input(command: str) -> dict[str, Any]:
    optional = command in ("init", "recover", "list")
    raw = sys.stdin.readline()
    if raw == "":
        if optional:
            return {}
        raise SpoolError("INVALID_INPUT", "expected one JSON object on stdin", {})
    line = raw
    if line.endswith("\n"):
        line = line[:-1]
    if line.endswith("\r"):
        line = line[:-1]
    if line == "":
        if optional:
            return {}
        raise SpoolError("INVALID_INPUT", "expected one JSON object on stdin", {})
    try:
        data = json.loads(line)
    except json.JSONDecodeError as exc:
        raise SpoolError("INVALID_INPUT", "invalid JSON", {"error": str(exc)}) from exc
    if type(data) is not dict:
        raise SpoolError("INVALID_INPUT", "input must be a JSON object", {})
    return data


def _require_fields(data: dict[str, Any], fields: list[str]) -> None:
    for f in fields:
        if f not in data:
            raise SpoolError("INVALID_INPUT", f"missing field {f}", {"field": f})


_STORAGE_CODES = frozenset(
    {"CORRUPT_STATE", "LOCK_TIMEOUT", "INTERNAL_ERROR", "SCHEMA_MISMATCH"}
)


def main() -> None:
    parser = argparse.ArgumentParser(prog="delivery_spool", add_help=True)
    parser.add_argument("--root", required=True)
    parser.add_argument(
        "command",
        choices=["init", "enqueue", "claim", "ack", "fail", "recover", "show", "list"],
    )
    try:
        args = parser.parse_args()
    except SystemExit as exc:
        code = exc.code if isinstance(exc.code, int) else 2
        if code == 0:
            raise
        _emit(
            {
                "ok": False,
                "error": {
                    "code": "INVALID_INPUT",
                    "message": "invalid CLI arguments",
                    "details": {},
                },
            },
            2,
        )
        return

    try:
        data = _read_input(args.command)
        spool = Spool(
            args.root,
            clock=time.time,
            limits=Limits(),
            lock_timeout=10.0,
            failpoint=None,
        )

        if args.command == "init":
            unknown = set(data.keys())
            if unknown:
                raise SpoolError("INVALID_INPUT", "unknown fields", {"fields": sorted(unknown)})
            result = spool.initialize()
        elif args.command == "enqueue":
            _require_fields(data, ["message_id", "payload"])
            unknown = set(data.keys()) - {"message_id", "payload", "available_at"}
            if unknown:
                raise SpoolError("INVALID_INPUT", "unknown fields", {"fields": sorted(unknown)})
            if "available_at" in data:
                result = spool.enqueue(data["message_id"], data["payload"], data["available_at"])
            else:
                result = spool.enqueue(data["message_id"], data["payload"])
        elif args.command == "claim":
            _require_fields(data, ["worker_id"])
            unknown = set(data.keys()) - {"worker_id"}
            if unknown:
                raise SpoolError("INVALID_INPUT", "unknown fields", {"fields": sorted(unknown)})
            result = spool.claim(data["worker_id"])
        elif args.command == "ack":
            _require_fields(data, ["message_id", "lease_token"])
            unknown = set(data.keys()) - {"message_id", "lease_token"}
            if unknown:
                raise SpoolError("INVALID_INPUT", "unknown fields", {"fields": sorted(unknown)})
            result = spool.ack(data["message_id"], data["lease_token"])
        elif args.command == "fail":
            _require_fields(data, ["message_id", "lease_token", "error"])
            unknown = set(data.keys()) - {"message_id", "lease_token", "error"}
            if unknown:
                raise SpoolError("INVALID_INPUT", "unknown fields", {"fields": sorted(unknown)})
            result = spool.fail(data["message_id"], data["lease_token"], data["error"])
        elif args.command == "recover":
            unknown = set(data.keys())
            if unknown:
                raise SpoolError("INVALID_INPUT", "unknown fields", {"fields": sorted(unknown)})
            result = spool.recover()
        elif args.command == "show":
            _require_fields(data, ["message_id"])
            unknown = set(data.keys()) - {"message_id"}
            if unknown:
                raise SpoolError("INVALID_INPUT", "unknown fields", {"fields": sorted(unknown)})
            result = spool.get(data["message_id"])
        elif args.command == "list":
            unknown = set(data.keys()) - {"status"}
            if unknown:
                raise SpoolError("INVALID_INPUT", "unknown fields", {"fields": sorted(unknown)})
            if "status" in data:
                result = spool.list_messages(data["status"])
            else:
                result = spool.list_messages()
        else:
            raise SpoolError("INVALID_INPUT", "unknown command", {"command": args.command})

        _emit({"ok": True, "result": result}, 0)
    except SpoolError as err:
        exit_code = 3 if err.code in _STORAGE_CODES else 2
        _emit(
            {
                "ok": False,
                "error": {
                    "code": err.code,
                    "message": err.message,
                    "details": err.details,
                },
            },
            exit_code,
        )
    except Exception as exc:  # noqa: BLE001
        _emit(
            {
                "ok": False,
                "error": {
                    "code": "INTERNAL_ERROR",
                    "message": "internal failure",
                    "details": {"error": str(exc)},
                },
            },
            3,
        )


if __name__ == "__main__":
    main()

